140: static __rte_always_inline uint16_t
141: vhost_async_dma_transfer(struct virtio_net *dev, struct vhost_virtqueue *vq,
142: 		int16_t dma_id, uint16_t vchan_id, uint16_t head_idx,
143: 		struct vhost_iov_iter *pkts, uint16_t nr_pkts)
144: 	__rte_requires_shared_capability(&vq->access_lock)
145: {
146: 	struct async_dma_vchan_info *dma_info = &dma_copy_track[dma_id].vchans[vchan_id];
147: 	int64_t ret, nr_copies = 0;
148: 	uint16_t pkt_idx;
149: 
150: 	rte_spinlock_lock(&dma_info->dma_lock);
151: 
152: 	for (pkt_idx = 0; pkt_idx < nr_pkts; pkt_idx++) {
153: 		ret = vhost_async_dma_transfer_one(dev, vq, dma_id, vchan_id, head_idx,
154: 				&pkts[pkt_idx]);
155: 		if (unlikely(ret < 0))
156: 			break;
157: 
158: 		nr_copies += ret;
159: 		head_idx++;
160: 		if (head_idx >= vq->size)
161: 			head_idx -= vq->size;
162: 	}
163: 
164: 	if (likely(nr_copies > 0))
165: 		rte_dma_submit(dma_id, vchan_id);
166: 
167: 	rte_spinlock_unlock(&dma_info->dma_lock);
168: 
169: 	return pkt_idx;

173: vhost_async_dma_check_completed(struct virtio_net *dev, int16_t dma_id, uint16_t vchan_id,
174: 		uint16_t max_pkts)
175: {
176: 	struct async_dma_vchan_info *dma_info = &dma_copy_track[dma_id].vchans[vchan_id];
177: 	uint16_t ring_mask = dma_info->ring_mask;
178: 	uint16_t last_idx = 0;
179: 	uint16_t nr_copies;
180: 	uint16_t copy_idx;
181: 	uint16_t i;
182: 	bool has_error = false;
183: 	static bool vhost_async_dma_complete_log;
184: 
185: 	rte_spinlock_lock(&dma_info->dma_lock);
186: 
187: 	/**
188: 	 * Print error log for debugging, if DMA reports error during
189: 	 * DMA transfer. We do not handle error in vhost level.
190: 	 */
191: 	nr_copies = rte_dma_completed(dma_id, vchan_id, max_pkts, &last_idx, &has_error);
192: 	if (unlikely(!vhost_async_dma_complete_log && has_error)) {
193: 		VHOST_DATA_LOG(dev->ifname, ERR,
194: 			"DMA completion failure on channel %d:%u",
195: 			dma_id, vchan_id);
196: 		vhost_async_dma_complete_log = true;
197: 	} else if (nr_copies == 0) {
198: 		goto out;
199: 	}
200: 
201: 	copy_idx = last_idx - nr_copies + 1;
202: 	for (i = 0; i < nr_copies; i++) {
203: 		bool *flag;
204: 
205: 		flag = dma_info->pkts_cmpl_flag_addr[copy_idx & ring_mask];
206: 		if (flag) {
207: 			/**
208: 			 * Mark the packet flag as received. The flag
209: 			 * could belong to another virtqueue but write
210: 			 * is atomic.
211: 			 */
212: 			*flag = true;
213: 			dma_info->pkts_cmpl_flag_addr[copy_idx & ring_mask] = NULL;
214: 		}
215: 		copy_idx++;
216: 	}
217: 
218: out:
219: 	rte_spinlock_unlock(&dma_info->dma_lock);
220: 	return nr_copies;

1799: virtio_dev_rx_async_submit_split(struct virtio_net *dev, struct vhost_virtqueue *vq,
1800: 	struct rte_mbuf **pkts, uint32_t count, int16_t dma_id, uint16_t vchan_id)
1801: 	__rte_requires_capability(&vq->access_lock)
1802: 	__rte_requires_shared_capability(&vq->iotlb_lock)
1803: {
1804: 	struct buf_vector buf_vec[BUF_VECTOR_MAX];
1805: 	uint32_t pkt_idx = 0;
1806: 	uint16_t num_buffers;
1807: 	uint16_t avail_head;
1808: 
1809: 	struct vhost_async *async = vq->async;
1810: 	struct async_inflight_info *pkts_info = async->pkts_info;
1811: 	uint32_t pkt_err = 0;
1812: 	uint16_t n_xfer;
1813: 	uint16_t slot_idx = 0;
1814: 
1815: 	/*
1816: 	 * The ordering between avail index and desc reads need to be enforced.
1817: 	 */
1818: 	avail_head = rte_atomic_load_explicit((unsigned short __rte_atomic *)&vq->avail->idx,
1819: 		rte_memory_order_acquire);
1820: 
1821: 	rte_prefetch0(&vq->avail->ring[vq->last_avail_idx & (vq->size - 1)]);
1822: 
1823: 	async_iter_reset(async);
1824: 
1825: 	for (pkt_idx = 0; pkt_idx < count; pkt_idx++) {
1826: 		uint64_t pkt_len = pkts[pkt_idx]->pkt_len + dev->vhost_hlen;
1827: 		uint16_t nr_vec = 0;
1828: 
1829: 		if (unlikely(reserve_avail_buf_split(dev, vq, pkt_len, buf_vec,
1830: 						&num_buffers, avail_head, &nr_vec) < 0)) {
1831: 			VHOST_DATA_LOG(dev->ifname, DEBUG,
1832: 				"failed to get enough desc from vring");
1833: 			vq->shadow_used_idx -= num_buffers;
1834: 			break;
1835: 		}
1836: 
1837: 		VHOST_DATA_LOG(dev->ifname, DEBUG,
1838: 			"current index %d | end index %d",
1839: 			vq->last_avail_idx, vq->last_avail_idx + num_buffers);
1840: 
1841: 		if (mbuf_to_desc(dev, vq, pkts[pkt_idx], buf_vec, nr_vec, num_buffers, true) < 0) {
1842: 			vq->shadow_used_idx -= num_buffers;
1843: 			break;
1844: 		}
1845: 
1846: 		slot_idx = (async->pkts_idx + pkt_idx) & (vq->size - 1);
1847: 		pkts_info[slot_idx].descs = num_buffers;
1848: 		pkts_info[slot_idx].mbuf = pkts[pkt_idx];
1849: 
1850: 		vq->last_avail_idx += num_buffers;
1851: 		vhost_virtqueue_reconnect_log_split(vq);
1852: 	}
1853: 
1854: 	if (unlikely(pkt_idx == 0))
1855: 		return 0;
1856: 
1857: 	n_xfer = vhost_async_dma_transfer(dev, vq, dma_id, vchan_id, async->pkts_idx,
1858: 			async->iov_iter, pkt_idx);

2277: vhost_poll_enqueue_completed(struct virtio_net *dev, struct vhost_virtqueue *vq,
2278: 	struct rte_mbuf **pkts, uint16_t count, int16_t dma_id, uint16_t vchan_id)
2279: 	__rte_requires_shared_capability(&vq->access_lock)
2280: {
2281: 	struct vhost_async *async = vq->async;
2282: 	struct async_inflight_info *pkts_info = async->pkts_info;
2283: 	uint16_t nr_cpl_pkts = 0;
2284: 	uint16_t n_descs = 0, n_buffers = 0;
2285: 	uint16_t start_idx, from, i;
2286: 
2287: 	/* Check completed copies for the given DMA vChannel */
2288: 	vhost_async_dma_check_completed(dev, dma_id, vchan_id, VHOST_DMA_MAX_COPY_COMPLETE);
2289: 
2290: 	start_idx = async_get_first_inflight_pkt_idx(vq);
2291: 	/**
2292: 	 * Calculate the number of copy completed packets.
2293: 	 * Note that there may be completed packets even if
2294: 	 * no copies are reported done by the given DMA vChannel,
2295: 	 * as it's possible that a virtqueue uses multiple DMA
2296: 	 * vChannels.
2297: 	 */
2298: 	from = start_idx;
2299: 	while (vq->async->pkts_cmpl_flag[from] && count--) {
2300: 		vq->async->pkts_cmpl_flag[from] = false;
2301: 		from++;
2302: 		if (from >= vq->size)
2303: 			from -= vq->size;
2304: 		nr_cpl_pkts++;
2305: 	}
2306: 
2307: 	if (nr_cpl_pkts == 0)
2308: 		return 0;
2309: 
2310: 	for (i = 0; i < nr_cpl_pkts; i++) {
2311: 		from = (start_idx + i) % vq->size;
2312: 		/* Only used with packed ring */
2313: 		n_buffers += pkts_info[from].nr_buffers;
2314: 		/* Only used with split ring */
2315: 		n_descs += pkts_info[from].descs;
2316: 		pkts[i] = pkts_info[from].mbuf;
2317: 	}
2318: 
2319: 	async->pkts_inflight_n -= nr_cpl_pkts;
2320: 
2321: 	if (likely(vq->enabled && vq->access_ok)) {
2322: 		if (vq_is_packed(dev)) {
2323: 			write_back_completed_descs_packed(vq, n_buffers);
2324: 			vhost_vring_call_packed(dev, vq);
2325: 		} else {
2326: 			write_back_completed_descs_split(vq, n_descs);
2327: 			rte_atomic_fetch_add_explicit(
2328: 				(unsigned short __rte_atomic *)&vq->used->idx,
2329: 				n_descs, rte_memory_order_release);
2330: 			vhost_vring_call_split(dev, vq);
2331: 		}
2332: 	} else {
2333: 		if (vq_is_packed(dev)) {
2334: 			async->last_buffer_idx_packed += n_buffers;
2335: 			if (async->last_buffer_idx_packed >= vq->size)
2336: 				async->last_buffer_idx_packed -= vq->size;
2337: 		} else {
2338: 			async->last_desc_idx_split += n_descs;
2339: 		}
2340: 	}
2341: 
2342: 	return nr_cpl_pkts;

3706: async_poll_dequeue_completed(struct virtio_net *dev, struct vhost_virtqueue *vq,
3707: 		struct rte_mbuf **pkts, uint16_t count, int16_t dma_id,
3708: 		uint16_t vchan_id, bool legacy_ol_flags)
3709: 	__rte_requires_shared_capability(&vq->access_lock)
3710: {
3711: 	uint16_t start_idx, from, i;
3712: 	uint16_t nr_cpl_pkts = 0;
3713: 	struct async_inflight_info *pkts_info = vq->async->pkts_info;
3714: 
3715: 	vhost_async_dma_check_completed(dev, dma_id, vchan_id, VHOST_DMA_MAX_COPY_COMPLETE);
3716: 
3717: 	start_idx = async_get_first_inflight_pkt_idx(vq);
3718: 
3719: 	from = start_idx;
3720: 	while (vq->async->pkts_cmpl_flag[from] && count--) {
3721: 		vq->async->pkts_cmpl_flag[from] = false;
3722: 		from = (from + 1) % vq->size;
3723: 		nr_cpl_pkts++;
3724: 	}
3725: 
3726: 	if (nr_cpl_pkts == 0)
3727: 		return 0;
3728: 
3729: 	for (i = 0; i < nr_cpl_pkts; i++) {
3730: 		from = (start_idx + i) % vq->size;
3731: 		pkts[i] = pkts_info[from].mbuf;
3732: 
3733: 		if (virtio_net_with_host_offload(dev))
3734: 			vhost_dequeue_offload(dev, &pkts_info[from].nethdr, pkts[i],
