3754: virtio_dev_tx_async_split(struct virtio_net *dev, struct vhost_virtqueue *vq,
3755: 		struct rte_mempool *mbuf_pool, struct rte_mbuf **pkts, uint16_t count,
3756: 		int16_t dma_id, uint16_t vchan_id, bool legacy_ol_flags)
3757: 	__rte_requires_shared_capability(&vq->access_lock)
3758: 	__rte_requires_shared_capability(&vq->iotlb_lock)
3759: {
3760: 	static bool allocerr_warned;
3761: 	bool dropped = false;
3762: 	uint16_t avail_entries;
3763: 	uint16_t pkt_idx, slot_idx = 0;
3764: 	uint16_t nr_done_pkts = 0;
3765: 	uint16_t pkt_err = 0;
3766: 	uint16_t n_xfer;
