3777: 		rte_memory_order_acquire) - vq->last_avail_idx;
3778: 	if (avail_entries == 0)
3779: 		goto out;

3836: 		slot_idx = (async->pkts_idx + pkt_idx) & (vq->size - 1);
3837: 		err = desc_to_mbuf(dev, vq, buf_vec, nr_vec, pkt, mbuf_pool,
3838: 					legacy_ol_flags, slot_idx, true);
3839: 		if (unlikely(err)) {
3840: 			if (!allocerr_warned) {
3841: 				VHOST_DATA_LOG(dev->ifname, ERR,
3842: 					"%s: Failed to offload copies to async channel.",
3843: 					__func__);
3844: 				allocerr_warned = true;
3845: 			}
3846: 			dropped = true;
3847: 			slot_idx--;
3848: 			break;
3849: 		}
3850: 
3851: 		pkts_info[slot_idx].mbuf = pkt;
3852: 
3853: 		/* store used descs */
3854: 		to = async->desc_idx_split & (vq->size - 1);
3855: 		async->descs_split[to].id = head_idx;
3856: 		async->descs_split[to].len = 0;
3857: 		async->desc_idx_split++;
3858: 
3859: 		vq->last_avail_idx++;
3860: 		vhost_virtqueue_reconnect_log_split(vq);

3866: 	n_xfer = vhost_async_dma_transfer(dev, vq, dma_id, vchan_id, async->pkts_idx,
3867: 					  async->iov_iter, pkt_idx);
3868: 
3869: 	async->pkts_inflight_n += n_xfer;
3870: 
3871: 	pkt_err = pkt_idx - n_xfer;
3872: 	if (unlikely(pkt_err)) {
3873: 		VHOST_DATA_LOG(dev->ifname, DEBUG, "%s: failed to transfer data.",
3874: 			__func__);
3875: 
3876: 		pkt_idx = n_xfer;
3877: 		/* recover available ring */
3878: 		vq->last_avail_idx -= pkt_err;
3879: 		vhost_virtqueue_reconnect_log_split(vq);
3880: 
3881: 		/**
3882: 		 * recover async channel copy related structures and free pktmbufs
3883: 		 * for error pkts.
3884: 		 */
3885: 		async->desc_idx_split -= pkt_err;
3886: 		while (pkt_err-- > 0) {
3887: 			rte_pktmbuf_free(pkts_info[slot_idx & (vq->size - 1)].mbuf);
3888: 			slot_idx--;
3889: 		}
3890: 	}
3891: 
3892: 	async->pkts_idx += pkt_idx;
3893: 	if (async->pkts_idx >= vq->size)
3894: 		async->pkts_idx -= vq->size;
3895: 
3896: out:
3897: 	/* DMA device may serve other queues, unconditionally check completed. */
3898: 	nr_done_pkts = async_poll_dequeue_completed(dev, vq, pkts, pkts_size,
3899: 							dma_id, vchan_id, legacy_ol_flags);
3900: 
3901: 	return nr_done_pkts;

