173: virtqueue_dequeue_burst_rx(struct virtqueue *vq, struct rte_mbuf **rx_pkts,
174: 			   uint32_t *len, uint16_t num)
175: {
176: 	struct vring_used_elem *uep;
177: 	struct rte_mbuf *cookie;
178: 	uint16_t used_idx, desc_idx;
179: 	uint16_t i;
180: 
