182: 	for (i = 0; i < num ; i++) {
183: 		used_idx = (uint16_t)(vq->vq_used_cons_idx & (vq->vq_nentries - 1));
184: 		uep = &vq->vq_split.ring.used->ring[used_idx];
185: 		desc_idx = (uint16_t) uep->id;
186: 		len[i] = uep->len;
187: 		cookie = (struct rte_mbuf *)vq->vq_descx[desc_idx].cookie;
188: 
189: 		if (unlikely(cookie == NULL)) {
190: 			PMD_DRV_LOG(ERR, "vring descriptor with no mbuf cookie at %u",
191: 				vq->vq_used_cons_idx);
