193: 		}
194: 
195: 		rte_prefetch0(cookie);
196: 		rte_packet_prefetch(rte_pktmbuf_mtod(cookie, void *));
197: 		rx_pkts[i]  = cookie;
198: 		vq->vq_used_cons_idx++;
199: 		vq_ring_free_chain(vq, desc_idx);
200: 		vq->vq_descx[desc_idx].cookie = NULL;
201: 	}
202: 
203: 	return i;

285: virtqueue_enqueue_recv_refill(struct virtqueue *vq, struct rte_mbuf **cookie,
286: 				uint16_t num)
287: {
288: 	struct vq_desc_extra *dxp;
