1036: 
1037: 		rxm->port = hw->port_id;
1038: 		rxm->data_off = RTE_PKTMBUF_HEADROOM;
1039: 		rxm->ol_flags = 0;
1040: 		rxm->vlan_tci = 0;
1041: 
1042: 		rxm->pkt_len = (uint32_t)(len[i] - hdr_size);
1043: 		rxm->data_len = (uint16_t)(len[i] - hdr_size);
1044: 
1045: 		hdr = (struct virtio_net_hdr *)((char *)rxm->buf_addr +
