29: inline std::vector<Span> spans() {
30:   std::vector<Span> out;
31:   for(const auto& p:packets()) {
32:     size_t si=0,di=0; uint32_t so=0,dof=kHeaderBytes,left=p.length;
33:     while(left) {
34:       if(si>=p.source.size() || di>=p.destination.size()) throw std::runtime_error("capacity exhausted");
35:       const auto& s=p.source[si]; const auto& d=p.destination[di];
36:       uint32_t n=std::min({left,s.length-so,d.capacity-dof});
37:       if(!n) throw std::runtime_error("zero span");
38:       out.push_back({p.packet_id,s.offset+so,d.offset+dof,n}); left-=n;so+=n;dof+=n;
39:       if(so==s.length){++si;so=0;} if(dof==d.capacity){++di;dof=0;}
40:     }
41:   }
42:   return out;
43: }
44: // Caller must establish completed reads/writes and quiet before this software handoff.
45: // This helper is deliberately not a hardware completion oracle.
46: inline std::vector<Used> publish_after_quiet(std::vector<uint8_t>& m) {
47:   if(m.size()!=kMemoryBytes) throw std::runtime_error("wrong memory size");
48:   std::vector<Used> out;
49:   for(const auto& p:packets()) {
50:     std::copy(header().begin(),header().end(),m.begin()+p.destination.front().offset);
51:     out.push_back({p.cookie_id,kHeaderBytes+p.length});
52:   }
53:   return out;

58: inline CheckResult consume(const std::vector<uint8_t>& m,const std::vector<Used>& used) {
59:   CheckResult r{false,"",0,0,0,1469598103934665603ull};
60:   auto fail=[&](const std::string& s){r.reason=s;return r;};
61:   if(m.size()!=kMemoryBytes) return fail("memory size");
62:   if(used.size()!=packets().size()) return fail("used count");
63:   std::array<bool,kMemoryBytes> touched{};
64:   std::unordered_set<uint32_t> consumed;
65:   for(size_t order=0;order<used.size();++order) {
66:     const auto& u=used[order]; const Packet* packet=nullptr;
67:     for(const auto& p:packets()) if(p.cookie_id==u.id) packet=&p;
68:     if(!packet || !consumed.insert(u.id).second) return fail("wrong or repeated original cookie");
69:     const auto& p=*packet;
70:     if(p.order!=order) return fail("publication order");
71:     if(u.length!=kHeaderBytes+p.length) return fail("used length");
72:     uint32_t id=u.id,left=u.length,logical=0;
73:     std::unordered_set<uint32_t> visited;
74:     while(left) {
75:       const Descriptor* desc=nullptr;
76:       for(const auto& d:p.destination) if(d.id==id) desc=&d;
77:       if(!desc || !visited.insert(id).second) return fail("invalid descriptor chain");
78:       const auto& d=*desc; uint32_t n=std::min(left,d.capacity);
79:       if(d.offset<kSourceEnd || uint64_t(d.offset)+n>m.size()) return fail("destination bounds");
80:       for(uint32_t j=0;j<n;++j,++logical) {
81:         uint8_t expected=logical<kHeaderBytes?header()[logical]:p.frame[logical-kHeaderBytes];
82:         if(m[d.offset+j]!=expected) return fail(logical<kHeaderBytes?"virtio header mismatch":"frame byte mismatch");
83:         if(touched[d.offset+j]) return fail("overlapping receive records");
84:         touched[d.offset+j]=true; ++r.record_bytes;
85:         if(logical>=kHeaderBytes){++r.frame_bytes;r.digest=(r.digest^m[d.offset+j])*1099511628211ull;}
86:       }
87:       left-=n;if(left && !d.has_next) return fail("descriptor capacity"); id=d.next;
88:     }
89:   }
90:   for(uint32_t i=kSourceEnd;i<kMemoryBytes;++i) if(!touched[i]) {
91:     ++r.guard_bytes;if(m[i]!=0xa5) return fail("destination neighbor guard overwritten");
92:   }
93:   r.ok=true;r.reason="complete original-cookie records and guards verified";return r;

